// Reçoit un message "up" de TTN (déjà décodé par le formateur CayenneLPP)
const up = msg.payload;
const um = up.uplink_message || {};
const dec = um.decoded_payload || {};

// Les noms des champs décodés finissent par le numéro de canal (ex. temperature_1)
function trouver(prefixes) {
    for (const k of Object.keys(dec)) {
        for (const p of prefixes) {
            if (k.indexOf(p) === 0) { return dec[k]; }
        }
    }
    return undefined;
}
const temperature = trouver(['temperature']);
const humidity = trouver(['relative_humidity', 'humidity']);
if (temperature === undefined || humidity === undefined) {
    node.warn('Payload décodé inattendu : ' + JSON.stringify(dec));
    return null;
}

const rx = (um.rx_metadata && um.rx_metadata[0]) || {};
const gw = rx.gateway_ids ? rx.gateway_ids.gateway_id : 'n/a';
const dev = up.end_device_ids ? up.end_device_ids.device_id : 'n/a';
const t = up.received_at ? new Date(up.received_at).toLocaleTimeString('fr-FR') : 'n/a';
const fcnt = (um.f_cnt !== undefined) ? um.f_cnt : 'n/a';

const infos = {
    device_id: dev, fcnt: fcnt, fport: um.f_port, received_at: up.received_at,
    gateway_id: gw, rssi: rx.rssi, snr: rx.snr,
    temperature: temperature, humidity: humidity
};
const texte = '#' + fcnt + ' | ' + dev + ' | passerelle ' + gw +
              ' | RSSI ' + rx.rssi + ' dBm | SNR ' + rx.snr + ' dB | reçu à ' + t;

node.status({fill: 'green', shape: 'dot', text: temperature + ' °C / ' + humidity + ' %'});
return [
    {payload: infos},
    {payload: temperature, topic: 'Température'},
    {payload: humidity, topic: 'Humidité'},
    {payload: texte}
];

// RÈGLES D'ALERTE : compare les mesures aux seuils réglables sur le dashboard
let sT = flow.get('seuilT'); if (sT === undefined) { sT = 27; }   // °C
let sH = flow.get('seuilH'); if (sH === undefined) { sH = 90; }   // %
let last = flow.get('last');                                       // dernières mesures
const heure = new Date().toLocaleTimeString('fr-FR');

// 1) Que reçoit-on ? un seuil modifié, le bouton de test, ou une nouvelle mesure
if (msg.topic === 'seuilT') {
    sT = Number(msg.payload); flow.set('seuilT', sT);
} else if (msg.topic === 'seuilH') {
    sH = Number(msg.payload); flow.set('seuilH', sH);
} else if (msg.topic === 'test') {
    const texte = 'Alerte de test déclenchée à ' + heure;
    return [
        {payload: texte, topic: 'ALERTE (test)'},
        {payload: '⚠️ ALERTE (test)'},
        {payload: heure + ' : alerte de test'},
        {payload: 'Seuils : T > ' + sT + ' °C | H > ' + sH + ' %'}
    ];
} else if (msg.payload && msg.payload.temperature !== undefined) {
    last = msg.payload; flow.set('last', last);
}

const seuils = {payload: 'Seuils : T > ' + sT + ' °C | H > ' + sH + ' %'};
if (!last) {
    return [null, {payload: 'En attente de mesures...'}, null, seuils];
}

// 2) Évaluation
const alertes = [];
if (last.temperature > sT) { alertes.push('Température ' + last.temperature + ' °C > seuil ' + sT + ' °C'); }
if (last.humidity > sH)    { alertes.push('Humidité ' + last.humidity + ' % > seuil ' + sH + ' %'); }

if (alertes.length > 0) {
    node.status({fill: 'red', shape: 'dot', text: 'ALERTE'});
    return [
        {payload: alertes.join(' ; '), topic: 'ALERTE'},          // notification
        {payload: '⚠️ ALERTE : ' + alertes.join(' ; ')},           // état
        {payload: heure + ' : ' + alertes.join(' ; ')},            // dernière alerte
        seuils
    ];
}
node.status({fill: 'green', shape: 'dot', text: 'normal'});
return [null, {payload: '✅ Normal : ' + last.temperature + ' °C, ' + last.humidity + ' %'}, null, seuils];
